def cap_max(txt):
    if txt and ('≤20' in txt or '<=20' in txt):
        return 20
    nums=[int(x) for x in re.findall(r'\b\d{1,3}\b', txt or '')]
    nums=[n for n in nums if n<=300]
    return max(nums) if nums else None

def price_score(txt):
    if not txt: return 45
    t=txt.lower()
    if 'gratuit' in t or 'exonération' in t: return 100
    nums=[float(x.replace(',','.')) for x in re.findall(r'\b\d+(?:[,.]\d+)?\b', t)]
    # Heuristic: if hourly <=20 excellent, <=50 ok; daily <=120 excellent, <=250 ok
    if any(n<=20 for n in nums) and ('h' in t or 'heure' in t): return 90
    if any(n<=50 for n in nums) and ('h' in t or 'heure' in t): return 75
    if any(n<=120 for n in nums) and ('jour' in t or 'journée' in t): return 80
    if any(n<=250 for n in nums) and ('jour' in t or 'journée' in t): return 65
    return 50

def geocode(addr):
    q=urllib.parse.urlencode({'q':addr,'limit':1})
    req=urllib.request.Request('https://api-adresse.data.gouv.fr/search/?'+q, headers={'User-Agent':'Hermes small rooms map'})
    try:
        with urllib.request.urlopen(req, timeout=10) as r: js=json.load(r)
        if js.get('features'):
            f=js['features'][0]; lon,lat=f['geometry']['coordinates']; p=f['properties']
            return lat,lon,p.get('score'),p.get('label')
    except Exception as e:
        return None,None,None,str(e)
    return None,None,None,None
rows=[]; features=[]
for i,v in enumerate(venues,1):
    lat,lon,gs,gl=geocode(v['address']); time.sleep(.08)
    cmax=cap_max(v['capacity_text'])
    ps=price_score(v.get('price_text'))
    fit=0
    if cmax and cmax<=20: fit+=35
    elif cmax and cmax<=25: fit+=20
    fit+=round(ps*.35)
    if v['department'] in {'75','92','93','94'}: fit+=15
    elif v['department'] in {'78','91','95'}: fit+=8
    if v.get('contact'): fit+=8
    if v['confidence']=='high': fit+=7
    if 'municipal' in v['category'] or 'associations' in v['category']: fit+=5
    rid=f"small-{i:03d}"
    rec={**v,'id':rid,'lat':lat,'lon':lon,'geocode_score':gs,'geocode_label':gl,'capacity_max_detected':cmax or '', 'price_score':ps,'fit_score':min(fit,100),'last_checked':'2026-06-19'}
    rec['pros']=' | '.join(v['pros']); rec['cons']=' | '.join(v['cons']); rec['price_text']=v.get('price_text') or ''
    rows.append(rec)
    if lat and lon: features.append({'type':'Feature','geometry':{'type':'Point','coordinates':[lon,lat]},'properties':rec})
fields=['id','name','city','department','address','lat','lon','geocode_score','geocode_label','category','capacity_text','capacity_max_detected','price_text','price_score','website','contact','source_url','pros','cons','confidence','fit_score','last_checked']
with open(DATA/'salles_small_idf.csv','w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows([{k:r.get(k,'') for k in fields} for r in rows])
with open(PUBLIC/'salles_small_idf.geojson','w',encoding='utf-8') as f:
    json.dump({'type':'FeatureCollection','features':features},f,ensure_ascii=False,indent=2)
html='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Petites salles IDF ≤20 pas chères</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>body{margin:0;font-family:system-ui}.panel{position:absolute;z-index:1000;top:10px;left:10px;background:white;border-radius:12px;padding:12px;box-shadow:0 2px 12px #0002;max-width:380px}#map{height:100vh}button{margin:2px;border:1px solid #ccc;border-radius:99px;padding:6px 9px}button.active{background:#111;color:#fff}.tag{display:inline-block;background:#eef;border-radius:6px;padding:2px 5px;margin:2px;font-size:12px}.popup{max-width:370px}</style></head><body><div id="map"></div><div class="panel"><b>Petites salles IDF ≤20 — budget bas</b><div id="count"></div><div id="filters"><button class="active" data-d="all">Tous</button><button data-d="75">75</button><button data-d="92">92</button><button data-d="93">93</button><button data-d="94">94</button><button data-d="78">78</button><button data-d="91">91</button><button data-d="95">95</button></div><small>Vert = meilleur fit prix/capacité. À confirmer avant réservation.</small></div><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const map=L.map('map').setView([48.86,2.35],10);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OSM'}).addTo(map);let group=L.layerGroup().addTo(map),data,dept='all';function col(s){return s>=85?'#0a7':s>=70?'#8bc34a':s>=55?'#ffc107':'#ff7043'}function render(){group.clearLayers();let n=0;data.features.forEach(f=>{let p=f.properties;if(dept!='all'&&p.department!=dept)return;n++;L.circleMarker([p.lat,p.lon],{radius:8,color:'#222',weight:1,fillColor:col(+p.fit_score),fillOpacity:.9}).addTo(group).bindPopup(`<div class=popup><h3>${p.name}</h3><span class=tag>${p.department}</span><span class=tag>${p.category}</span><span class=tag>fit ${p.fit_score}</span><p><b>Capacité</b>: ${p.capacity_text}</p><p><b>Prix</b>: ${p.price_text||'à confirmer'}</p><p><b>Contact</b>: ${p.contact||'à compléter'}</p><p><b>Pros</b>: ${p.pros}</p><p><b>Cons</b>: ${p.cons}</p><p><a href='${p.website}' target=_blank>site</a> · <a href='${p.source_url}' target=_blank>source</a></p></div>`)});document.getElementById('count').textContent=`${n} affichées / ${data.features.length} géocodées`}fetch('salles_small_idf.geojson').then(r=>r.json()).then(j=>{data=j;render()});document.querySelectorAll('button').forEach(b=>b.onclick=()=>{document.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');dept=b.dataset.d;render()})</script></body></html>'''
(PUBLIC/'small.html').write_text(html,encoding='utf-8')
print(json.dumps({'rows':len(rows),'geocoded':len(features),'csv':str(DATA/'salles_small_idf.csv'),'geojson':str(PUBLIC/'salles_small_idf.geojson'),'html':str(PUBLIC/'small.html')},ensure_ascii=False,indent=2))
